from collections import OrderedDict
from collections.abc import MutableMapping


class BoundedLRUDict(MutableMapping):
    def __init__(self, capacity, on_evict=None):
        if capacity < 1:
            raise ValueError('capacity must be >= 1')
        self.capacity = capacity
        self.on_evict = on_evict
        self._data = OrderedDict()

    def __getitem__(self, key):
        value = self._data[key]          # KeyError propagates -> get() returns default
        self._data.move_to_end(key)
        return value

    def __setitem__(self, key, value):
        if key in self._data:
            self._data[key] = value
            self._data.move_to_end(key)
            return
        if len(self._data) >= self.capacity:
            old_key, old_value = self._data.popitem(last=False)
            if self.on_evict:
                self.on_evict(old_key, old_value)
        self._data[key] = value

    def __delitem__(self, key):
        del self._data[key]

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)


# ---------------------------------------------------------------------------
# Test harness (do not change). ops: ["set", k, v] | ["get", k] | ["has", k] | ["len"]
# ---------------------------------------------------------------------------
def replay(capacity, ops):
    evicted = []
    d = BoundedLRUDict(capacity, on_evict=lambda k, v: evicted.append([k, v]))
    out = []
    for op in ops:
        if op[0] == "set":
            d[op[1]] = op[2]
        elif op[0] == "get":
            out.append(d.get(op[1]))
        elif op[0] == "has":
            out.append(op[1] in d)
        elif op[0] == "len":
            out.append(len(d))
    return {"out": out, "evicted": evicted, "keys": list(d.keys())}
